<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {RouterLink} from 'vue-router'
import api from '@/api/client'
const current=ref(''),next=ref(''),confirm=ref(''),message=ref(''),busy=ref(false)
const policyLoading=ref(true)
const prefixes=ref(''),smsLimit=ref(20),policyMessage=ref('')
const twilioSID=ref(''),twilioToken=ref(''),twilioDomainSID=ref(''),twilioCredentialListSID=ref(''),twilioAccounts=ref<string[]>([]),twilioMessage=ref('')
onMounted(async()=>{try{const p=(await api.get('/business/policy')).data;prefixes.value=(Array.isArray(p.allowed_prefixes)?p.allowed_prefixes:[]).join(', ');smsLimit.value=p.sms_per_minute}catch{policyMessage.value='Could not load usage controls'}finally{policyLoading.value=false}})
onMounted(async()=>{try{twilioAccounts.value=(await api.get('/system/twilio-accounts')).data.data||[]}catch{twilioMessage.value='Could not load Twilio account connections'}})
async function addTwilioAccount(){twilioMessage.value='';busy.value=true;try{await api.post('/system/twilio-accounts',{account_sid:twilioSID.value.trim(),auth_token:twilioToken.value,domain_sid:twilioDomainSID.value.trim(),credential_list_sid:twilioCredentialListSID.value.trim()});twilioAccounts.value=(await api.get('/system/twilio-accounts')).data.data||[];twilioSID.value='';twilioToken.value='';twilioDomainSID.value='';twilioCredentialListSID.value='';twilioMessage.value='Twilio account and secure SIP resources verified and saved on the server.'}catch(e){twilioMessage.value=(e as {response?:{data?:{error?:{message?:string}}}}).response?.data?.error?.message||'Twilio credentials could not be verified or saved'}finally{busy.value=false}}
async function policy(){busy.value=true;try{await api.put('/business/policy',{allowed_prefixes:prefixes.value.split(',').map(p=>p.trim()).filter(Boolean),sms_per_minute:smsLimit.value});policyMessage.value='Usage controls saved'}catch{policyMessage.value='Use prefixes such as +44, +91 and an SMS limit from 1 to 120'}finally{busy.value=false}}
async function change(){message.value='';if(next.value!==confirm.value){message.value='Passwords do not match';return}busy.value=true;try{await api.put('/me/password',{current_password:current.value,new_password:next.value});message.value='Administrator password changed';current.value='';next.value='';confirm.value=''}catch(e){message.value=(e as {response?:{data?:{error?:{message?:string}}}}).response?.data?.error?.message||'Password could not be changed'}finally{busy.value=false}}
</script>
<template><div class="space-y-6 settings-page"><h1 class="text-2xl font-semibold">Settings</h1><form @submit.prevent="change" class="settings-card space-y-4"><h2 class="font-semibold">Change your administrator password</h2><label class="block">Current password<input v-model="current" type="password" autocomplete="current-password" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">New password<input v-model="next" type="password" autocomplete="new-password" minlength="12" maxlength="72" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">Confirm password<input v-model="confirm" type="password" autocomplete="new-password" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p>{{message}}</p><button :disabled="busy" class="bg-primary text-white rounded px-4 py-2">Change password</button></form><form @submit.prevent="policy" class="settings-card space-y-4"><h2 class="font-semibold">Usage controls</h2><label class="block">Allowed international prefixes<input v-model="prefixes" :disabled="policyLoading" placeholder="+44, +91" class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p class="text-sm text-gray-500">Comma-separated prefixes for outgoing calls and SMS. An empty field allows all destinations. Choose only the countries your team needs.</p><label class="block">SMS per minute per number<input v-model.number="smsLimit" :disabled="policyLoading" type="number" min="1" max="120" required class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p class="text-sm text-gray-500">Up to two concurrent outgoing calls per SIP user.</p><p>{{policyMessage}}</p><button :disabled="busy||policyLoading" class="bg-primary text-white rounded px-4 py-2">Save usage controls</button></form><section class="settings-card space-y-4"><h2 class="font-semibold">Additional Twilio accounts</h2><p class="text-sm text-gray-500">Create a secure SIP Domain and a Credential List in the Twilio account first. Attach the Credential List to both Calls and Registrations. Account credentials are stored in a private server file; Auth Tokens are never shown again.</p><p v-if="twilioAccounts.length" class="text-sm">Connected Account SIDs: {{twilioAccounts.join(', ')}}</p><form @submit.prevent="addTwilioAccount" class="space-y-3"><label class="block">Twilio Account SID<input v-model="twilioSID" required pattern="AC[a-fA-F0-9]{32}" autocomplete="off" class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">Twilio Auth Token<input v-model="twilioToken" required type="password" autocomplete="new-password" class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">SIP Domain SID<input v-model="twilioDomainSID" required pattern="SD[a-fA-F0-9]{32}" autocomplete="off" class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><label class="block">Credential List SID<input v-model="twilioCredentialListSID" required pattern="CL[a-fA-F0-9]{32}" autocomplete="off" class="block w-full border rounded p-2 mt-1 dark:bg-gray-700"/></label><p aria-live="polite">{{twilioMessage}}</p><button :disabled="busy" class="bg-primary text-white rounded px-4 py-2">Verify and connect account</button></form></section><div class="settings-card space-y-3"><h2 class="font-semibold">Server configuration</h2><p>The primary Twilio account SID and Auth Token are managed in Coolify environment variables. The server must keep its SIP certificate renewal/export configured; phones use SRTP.</p><p>Call routing and voicemail rules can be managed under Call Routing. User provisioning is managed under SIP Users.</p><RouterLink to="/" class="block text-primary">Service health, backups and change history →</RouterLink><RouterLink to="/users" class="block text-primary">Manage web console administrators →</RouterLink></div></div></template>
